// GetManyByIDs retrieves multiple Task records by their IDs in a single query
func (r *TaskRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Task, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Task{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "title", "owner", "reviewer", "plan", "proof", "urgent", "attempts", "created_by", "status", "status_entered_at", "_version" FROM task WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Task, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Task{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempReviewer *types.IdentityUUID
		var tempPlan sql.NullString
		var tempProof sql.NullString
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Title,

			&entity.Owner,

			&tempReviewer,

			&tempPlan,

			&tempProof,

			&entity.Urgent,

			&entity.Attempts,

			&entity.CreatedBy,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempReviewer != nil {
			entity.Reviewer = tempReviewer
		}
		if tempPlan.Valid {
			entity.Plan = tempPlan.String
		}
		if tempProof.Valid {
			entity.Proof = tempProof.String
		}
		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := taskUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

